<script setup lang="ts">import {computed} from 'vue';import type {EChartsOption} from 'echarts';import BaseChart from '@/components/BaseChart.vue';import ScreenPanel from './ScreenPanel.vue';import type {DashboardMeasure,DashboardRecommendation} from '@/types';const props=defineProps<{measures:DashboardMeasure[];recommendations:DashboardRecommendation[]}>();const labels:Record<string,string>={ECONOMIC:'经济优先',REDUCTION:'减排优先',BALANCED:'综合平衡'},recommendChart=computed<EChartsOption>(()=>({xAxis:{type:'category',data:props.recommendations.map(x=>labels[x.profile])},yAxis:{type:'value'},series:[{type:'bar',name:'预计减排',data:props.recommendations.map(x=>x.reduction_t)}]}));</script>
<template><ScreenPanel title="低碳措施运行" link="/simulation"><div class="measure-grid"><div v-for="m in measures" :key="m.type" :class="{off:!m.enabled}"><b>{{m.type}}</b><span>{{m.enabled?'启用':'未启用'}}</span><small>{{m.summary}}</small></div></div></ScreenPanel><ScreenPanel title="低碳路径 Top 1" link="/recommendations" :empty="!recommendations.length" empty-text="暂无推荐结果"><BaseChart :option="recommendChart" height="130px"/><div class="recommend-list"><div v-for="r in recommendations" :key="r.profile"><b>{{labels[r.profile]}}</b><span>{{r.measures.join(' + ')||'暂无措施'}}</span><small>减排 {{r.reduction_t??'--'}} t · 投资 {{r.investment??'--'}} · 回收 {{r.payback_years??'--'}} 年 · 评分 {{r.score.toFixed(3)}}</small></div></div></ScreenPanel></template>
